use lb_codec::codec_fixtures;
use lb_cryptarchia_engine::Slot;
use lb_groth16::Fr;
use lb_key_management_system_keys::keys::{Ed25519PublicKey, Ed25519Signature};

use crate::{
    block::{BlockTransactionReferences, Proposal, References, SignedHeader, UncleHeaders},
    header::{ContentId, Header, HeaderId},
    mantle::{TxHash, ops::leader_claim::VoucherCm},
    proofs::leader_proof::Groth16LeaderProof,
};

/// The three real references every reference fixture below is built from.
fn three_references() -> BlockTransactionReferences {
    [
        TxHash([0x01u8; 32]).prefix(),
        TxHash([0x02u8; 32]).prefix(),
        TxHash([0x03u8; 32]).prefix(),
    ]
    .into()
}

fn three_uncle_headers() -> UncleHeaders {
    UncleHeaders::new([uncle(0x66), uncle(0x77), uncle(0x88)])
}

fn uncle(id: u8) -> SignedHeader {
    SignedHeader::new(header(id), Ed25519Signature::from_bytes(&[id; _]))
}

fn header(id: u8) -> Header {
    Header::new(
        HeaderId::from([id; 32]),
        ContentId::from([0x22u8; 32]),
        Slot::from(42u64),
        Groth16LeaderProof::from_parts(
            lb_pol::PoLProof::from_bytes(&[0x22u8; _]),
            Fr::from(0x5555u64),
            Ed25519PublicKey::from_bytes(&[0x33u8; _]).expect("valid key bytes"),
            VoucherCm::from(Fr::from(0x4444u64)),
        ),
    )
}

codec_fixtures!(
    References,
    Self { mempool_transactions: three_references() } => "0300010101010101010101010101010101010202020202020202020202020202020203030303030303030303030303030303"
);

// Layout: `header (297B) || signature (64B)`
codec_fixtures!(SignedHeader, uncle(0x66) => "");

// Layout: `count (1B LE) || count × signed_header`.
codec_fixtures!(
    UncleHeaders,
    Self::empty() => "00",
    three_uncle_headers() => ""
);

// `header (297B) || uncle_headers (1B count + count * 361B)
// || references (50B) || signature (64B)` — 1495 bytes with three uncles.
//
// `references` is a `BoundedVec` capped at 1024, so it carries a 2-byte
// little-endian length prefix ahead of its 3 * 16-byte hash prefixes.
codec_fixtures!(
    Proposal,
    Self {
        header: header(0x00),
        uncle_headers: three_uncle_headers(),
        references: References { mempool_transactions: three_references() },
        signature: Ed25519Signature::from_bytes(&[0x01u8; _]),
    } => ""
);
